import { NextResponse } from "next/server";
import fs from "node:fs";
import path from "node:path";
import { selectedMetrics } from "~/lib/selectedModel";

/**
 * Serves model results to the dashboard.
 *
 * Reads straight off disk from data/results2d/ rather than the database. Those
 * files are regenerated by every training run and live under the gitignored
 * data/ directory, so each teammate sees the results of whatever they last
 * trained locally. Nothing here contains patient data — metrics and case IDs
 * only.
 */

export const dynamic = "force-dynamic";

function projectRoot() {
  // client/nextjs -> repo root
  return path.resolve(process.cwd(), "..", "..");
}

function readJson(relative: string) {
  try {
    const p = path.join(projectRoot(), relative);
    if (!fs.existsSync(p)) return null;
    return JSON.parse(fs.readFileSync(p, "utf8"));
  } catch {
    return null;
  }
}

function countAnnotations() {
  try {
    const dir = path.join(projectRoot(), "data", "annotations");
    if (!fs.existsSync(dir)) return { total: 0, cases: [] as string[] };
    const cases = fs
      .readdirSync(dir)
      .filter((d) => fs.existsSync(path.join(dir, d, `${d}.seg.nrrd`)));
    return { total: cases.length, cases };
  } catch {
    return { total: 0, cases: [] as string[] };
  }
}

function worklistSummary() {
  try {
    const p = path.join(projectRoot(), "data", "worklist.csv");
    if (!fs.existsSync(p)) return null;
    const lines = fs.readFileSync(p, "utf8").trim().split(/\r?\n/);
    const head = lines[0].split(",");
    const iAssigned = head.indexOf("assigned_to");
    const iClass = head.indexOf("class");
    const iIso = head.indexOf("isotropic");

    const byPerson: Record<string, { total: number; isotropic: number; bme: number }> = {};
    for (const line of lines.slice(1)) {
      const c = line.split(",");
      const who = (iAssigned >= 0 ? c[iAssigned] : "") || "unassigned";
      byPerson[who] ??= { total: 0, isotropic: 0, bme: 0 };
      byPerson[who].total++;
      if (iIso >= 0 && c[iIso] === "True") byPerson[who].isotropic++;
      if (iClass >= 0 && c[iClass] === "bme") byPerson[who].bme++;
    }
    return { totalCases: lines.length - 1, byPerson };
  } catch {
    return null;
  }
}

export async function GET() {
  // The marked run, not whatever trained last. Falls back to the newest run
  // when nothing is marked, and says so via `explicit` so the page can show
  // "latest" rather than implying somebody chose it.
  const sel = selectedMetrics();
  const metrics2d = sel.metrics ?? readJson("data/results2d/metrics.json");
  const review2d = readJson("data/results2d/review.json");

  return NextResponse.json({
    twoD: {
      available: Boolean(metrics2d),
      metrics: metrics2d,
      selectedRun: sel.id,
      selectionExplicit: sel.explicit,
      reviewCount: Array.isArray(review2d) ? review2d.length : 0,
    },
    threeD: {
      available: false,
      annotations: countAnnotations(),
      worklist: worklistSummary(),
    },
  });
}
